/// A Stream is an instance of a source. The main difference is the parameters
/// field is not a ParameterDesc descriptor object but the actual, serialized
/// parameter values.
///
/// Code performing the operation on the source will be able to construct a
/// stream object from this description and downstream code will be able to
/// read from it.
#[derive(Default, PartialEq, Debug, Clone)]
pub struct Stream {
    pub flags: u32,
    pub metadata: Option<ObjectId>,
    pub metadata_revision: Option<ContentId>,
    pub options: Option<Vec<u8>>,
    pub parameters: Option<Vec<u8>>,
    pub schema: Schema,
    pub substreams: Option<Vec<ObjectId>>,
    pub url: String,
}

impl Stream {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsStream<'a>> {
        use crate::types::generated::stream_generated::StreamBuilder as FbsStreamBuilder;

        let metadata_offset = self.metadata.as_ref().map(|o| o.serialize_to(builder));
        let metadata_revision_offset = self
            .metadata_revision
            .as_ref()
            .map(|o| o.serialize_to(builder));
        let options_offset = self.options.as_ref().map(|v| {
            let options_offset = builder.create_vector(&v);
            options_offset
        });
        let parameters_offset = self.parameters.as_ref().map(|v| {
            let parameters_offset = builder.create_vector(&v);
            parameters_offset
        });
        let schema_offset = self.schema.serialize_to(builder);
        let substreams_offset = self.substreams.as_ref().map(|v| {
            let mut substreams_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                substreams_offsets.push(offset);
            }
            let substreams_offset = builder.create_vector(&substreams_offsets);
            substreams_offset
        });
        let url_offset = builder.create_string(&self.url);

        let mut bldr = FbsStreamBuilder::new(builder);
        bldr.add_flags(self.flags);
        if let Some(offset) = metadata_offset {
            bldr.add_metadata(offset);
        }
        if let Some(offset) = metadata_revision_offset {
            bldr.add_metadata_revision(offset);
        }
        if let Some(offset) = options_offset {
            bldr.add_options(offset);
        }
        if let Some(offset) = parameters_offset {
            bldr.add_parameters(offset);
        }
        bldr.add_schema(schema_offset);
        if let Some(offset) = substreams_offset {
            bldr.add_substreams(offset);
        }
        bldr.add_url(url_offset);
        bldr.finish()
    }
}

impl From<FbsStream<'_>> for Stream {
    fn from(fbs: FbsStream<'_>) -> Self {
        let flags = fbs.flags();
        let metadata = fbs.metadata().map(ObjectId::from);
        let metadata_revision = fbs.metadata_revision().map(ContentId::from);
        let options = if let Some(val) = fbs.options() {
            let mut options = Vec::new();
            for elem in val {
                options.push(elem.into());
            }

            Some(options)
        } else {
            None
        };

        let parameters = if let Some(val) = fbs.parameters() {
            let mut parameters = Vec::new();
            for elem in val {
                parameters.push(elem.into());
            }

            Some(parameters)
        } else {
            None
        };

        let schema = Schema::from(fbs.schema());
        let substreams = if let Some(val) = fbs.substreams() {
            let mut substreams = Vec::new();
            for elem in val {
                substreams.push(elem.into());
            }

            Some(substreams)
        } else {
            None
        };

        let url = fbs.url().to_owned();
        Self {
            flags,
            metadata,
            metadata_revision,
            options,
            parameters,
            schema,
            substreams,
            url,
        }
    }
}

impl Stream {
    pub fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    pub fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let fbs = flatbuffers::size_prefixed_root::<FbsStream>(bytes)?;
        Ok(Self::from(fbs))
    }
}

